Method.Implementation:
	Set tStatus = $$$OK
	Try {
		
		// Check permissions
		If ('$System.Security.Check("%Admin_Manage","Use")) {
			$$$ThrowStatus($$$ERROR($$$GeneralError,"You Do not have %Admin_Manage:USE privileges"))
		}
		Do ..Log(.pLogFile,$Classname(),"CheckPrivileges","You have %Admin_Manage:USE privilege")
		
		// Do the pre install init
		Set tStatus = ..PreInstallInit(.pOptions,.pLogFile)
		$$$ThrowOnError(tStatus)
		
		// Build the EAI Namespace/Database
		Set tStatus = ..BuildDBNS(.pLogFile)
		$$$ThrowOnError(tStatus)
		
		// Configure ITF_Services user and ITF-WebServices role
		Set tStatus = ..ConfigureDefaultSecurity(.pLogFile)
		$$$ThrowOnError(tStatus)
		
		// Create and configure the CSP application
		Set tStatus = ..BuildServicesCSPApp(.pLogFile)
		$$$ThrowOnError(tStatus)
		
		// Configure SQL gateway
		Set tStatus = ..ConfigureSQLGateway(.pLogFile)
		$$$ThrowOnError(tStatus)
		
		// Load and compile code
		Set tStatus = ..ImportCode(.pLogFile)
		$$$ThrowOnError(tStatus)
		
		// Create mapping(s) - package/global
		Set tStatus = ..ConfigureMappings(.pLogFile)
		$$$ThrowOnError(tStatus)
		
#;		// Do the pre install init
#;		Set tStatus = ..PostInstallInit(.pLogFile)
#;		$$$ThrowOnError(tStatus)
#;		
#;		// Enable and start production
#;		Set tStatus = ..ConfigureProduction(.pLogFile)
#;		$$$ThrowOnError(tStatus)
#;		
#;		// Trigger internal unit tests?
#;		Set tStatus = ..TestInstall(.pLogFile)
#;		$$$ThrowOnError(tStatus)
		
	} Catch eException {
		Set tStatus = eException.AsStatus()
	}
	Quit tStatus

	Set tStatus = $$$OK
	Try {
		Set tNamespace = $GET(^EAI.Setting("Namespace"))
		Set tRoutineDB = $GET(^EAI.Setting("RoutineDatabase"))
		Set tDataDB = $GET(^EAI.Setting("DataDatabase"))
		Set tDBResource = $GET(^EAI.Setting("DatabaseResource"))
		Set tDBPublicPermissions = $GET(^EAI.Setting("DatabasePublicPermissions"))
		
		Do ..Log(.pLogFile,$Classname(),"BuildDBNS","Building DBNS " _ tNamespace)
		
		// Run this from %SYS
		New $NAMESPACE
   		Set $NAMESPACE = "%SYS"
		
		// Check if database exists already
		If (##class(Config.Databases).Exists(tNamespace)) {
			Do ..Log(.pLogFile,$Classname(),"BuildDBNS","Namespace " _ tNamespace _ " already exists")
		} Else {
			// Prepare DB configs
			Set tMgrDir = $System.Util.ManagerDirectory()
			Set tDirPathToReplace = ##class(%File).NormalizeDirectory("/" _ ##class(%SYS.System).GetInstanceName() _ "/mgr/")
			Set tDataDir = ##class(%File).NormalizeDirectory($REPLACE(tMgrDir,tDirPathToReplace,"") _ "/namespace/" _ tRoutineDB _ "/")
			
			// Create the CACHE.DAT (if not already there)
			Set tStatus = ..CreateDatabase(tRoutineDB,tDataDir,tDBResource,tDBPublicPermissions,.tExists,.pLogFile)
			$$$ThrowOnError(tStatus)
			
		}
		
		// Check if exists already
		If (##class(Config.Namespaces).Exists(tNamespace)) {
			Do ..Log(.pLogFile,$Classname(),"BuildDBNS","Namespace " _ tNamespace_" already exists")
		} Else {
			// Create the Namespace
			Do ..Log(.pLogFile,$Classname(),"CreateNamespace","Creating " _ tNamespace _ " namespace")
		
			Kill tProperties
			Set tProperties("Globals") = tDataDB
			Set tProperties("Routines") = tRoutineDB
			Set pExisted = 0
			Set tStatus = ##Class(Config.Namespaces).Create(tNamespace,.tProperties)
			$$$ThrowOnError(tStatus)
			
			Do ..Log(.pLogFile,$Classname(),"CreateNamespace","Created namespace " _ tNamespace)
			
			// Enable Ensemble
			Do ..Log(.pLogFile,$Classname(),"BuildDBNS","Enabling Ensemble for namespace " _ tNamespace)
			Set tStatus = ##class(%Library.EnsembleMgr).EnableNamespace(tNamespace,1)
			$$$ThrowOnError(tStatus)
			
			Do ..Log(.pLogFile,$Classname(),"BuildDBNS","Ensemble has now been enabled for namespace " _ tNamespace)
		}
	} catch eException {
		Set tStatus = eException.AsStatus()
	} 
	Quit tStatus

	Set tStatus = $$$OK
	Try {
		Do ..Log(.pLogFile,$Classname(),"CreateDatabase","Creating " _ pName _ " database")

		If ($NAMESPACE '= "%SYS") {
			$$$ThrowStatus($$$ERROR($$$GeneralError, "Cannot create database. Not in %SYS NS."))
		}
		
		Set pDir = ##class(%File).NormalizeDirectory(pDir)
		Set:(pResource = "") pResource="%DB_%DEFAULT"
		Set tExists = ##class(%File).Exists(pDir _ "CACHE.DAT")
		
		// If the CACHE.DAT doesn't exist, let's create it
		If ('tExists) {
			Do ..Log(.pLogFile,$Classname(),"CreateDatabase","CACHE.DAT doesn't exist at: " _ pDir _ "CACHE.DAT")

			// Create the directory if necessary
			If ('##class(%File).DirectoryExists(pDir)) {
				If ('##class(%File).CreateDirectoryChain(pDir)) {
					$$$ThrowStatus($$$ERROR($$$GeneralError, "Failed to create directory chain: " _ pDir))
				}
				Do ..Log(.pLogFile,$Classname(),"CreateDatabase","Created dir chain to: " _ pDir)
			}
			
			// Create the .DAT file
			Set tStatus = $$CreateDatabase^%SYS.DATABASE(pDir)
			$$$ThrowOnError(tStatus)
		} Else {
			Do ..Log(.pLogFile,$Classname(),"CreateDatabase","CACHE.DAT at " _ pDir _ " already exists")	
		}
			
		// Confirm db doesn't exists configuration-wise
		Set tDBObj = "", tDBExists = 0
		Set tDBExists = ##class(Config.Databases).Exists(pName,.tDBObj)
		If ('tDBExists) {
			Set pExisted = 0
			Do ..Log(.pLogFile,$Classname(),"CreateDatabase","DB configuration for '" _ pName _"' doesn't exist. Creating.")
			
			// Create the database
			Kill tProperties
			Set tProperties("Directory") = pDir
			Set tStatus = ##class(Config.Databases).Create(pName,.tProperties)
			$$$ThrowOnError(tStatus)
			Do ..Log(.pLogFile,$Classname(),"CreateDatabase","Created DB configuration for'" _ pName _"'")

			// Assign the resource to the database
			Set tStatus = ##class(%EnsembleMgr).assignResourceToDB(pResource,pDir,pPublicPermissions)
			$$$ThrowOnError(tStatus)
			Do ..Log(.pLogFile,$Classname(),"CreateDatabase","Assigned resource to DB: " _ pResource _ "|" _ pPublicPermissions)
		}
					
		// Check that the database actually exists now ...
		If ('##class(%File).Exists(pDir_"CACHE.DAT")) {
			$$$ThrowStatus($$$ERROR($$$GeneralError, "DB doesn't exist on final check."))
		}
	} Catch eException {
		Set tStatus = eException.AsStatus()
	}
	Quit tStatus

Set tStatus = $$$OK Try {
Set tNamespace = $GET(^EAI.Setting("Namespace")) Set tAppName = $GET(^EAI.Setting("CSPAppName")) Set tRole = $GET(^EAI.Setting("DefaultServicesRole"))
Do ..Log(.pLogFile,$Classname(),"BuildServicesCSPApp","Building CSP Application " _ tAppName)
// Run this from %SYS New $NAMESPACE Set $NAMESPACE = "%SYS"
Set tSourceDir = ##class(%File).NormalizeDirectory($System.Util.InstallDirectory()_"csp/"_tAppName_"/") Set tExists = ##class(Security.Applications).Exists("/" _ tAppName) // Note: This does not update an existing application ! If ('tExists) {
// Create the new csp app Set tCSPApp = ##class(Security.Applications).%New() Set tCSPApp.Name = "/" _ tAppName Set tCSPApp.NameSpace = tNamespace Set tCSPApp.AutheEnabled = 32 Set tCSPApp.Enabled = 1 Set tCSPApp.Description = "CSP App for " _ tNamespace _ " web services" Set tCSPApp.Resource = "" Set tCSPApp.AutoCompile = 0 Set tCSPApp.Timeout= 900 Set tCSPApp.Path = tSourceDir Set tCSPApp.Recurse = 1 Set tCSPApp.LoginPage = "" Set tCSPApp.InbndWebServicesEnabled = 1 Set tCSPApp.TwoFactorEnabled = 0 Set tCSPApp.IsNameSpaceDefault = 0 Set tCSPApp.PermittedClasses = "" Do tCSPApp.MatchRoles.Insert(tRole) Set tCSPApp.Type = 2 Set tCSPApp.CookiePath = "/" _ tAppName _ "/" Set tCSPApp.LockCSPName = 0 Set tCSPApp.CSPZENEnabled = 1 Set tCSPApp.ServeFiles = 2 // Always and Cached Set tCSPApp.UseCookies = 2 // Set UseCookies to Always Set tCSPApp.DispatchClass = "EnsLib.REST.Service"
Set tStatus = tCSPApp.%Save() $$$ThrowOnError(tStatus)
Do ..Log(.pLogFile,$Classname(),"BuildServicesCSPApp","Created CSP application " _ tAppName) } Else { Do ..Log(.pLogFile,$Classname(),"BuildServicesCSPApp","CSP application " _ tAppName _ " already exists") } } Catch eException { Set tStatus = eException.AsStatus() }
Quit tStatus

	Set tStatus = $$$OK
	Try {
		
		Set tNamespace = $GET(^EAI.Setting("Namespace"))
		Set tRole = $GET(^EAI.Setting("DefaultServicesRole"))
		Set tDBResource = $GET(^EAI.Setting("DatabaseResource"))
		Set tUsername = $GET(^EAI.Setting("DefaultServicesUsername"))
		Set tPassword = $GET(^EAI.Setting("DefaultServicesPassword"))
		
		Do ..Log(.pLogFile,$Classname(),"ConfigureDefaultSecurity","Configuring default security")
		
		// Security is setup in %SYS namespace
		New $NAMESPACE
   		Set $NAMESPACE = "%SYS"
		
		// Create the default services role
		// Check if exists
		Set tExists = ##class(Security.Roles).Exists(tRole)
		If ('tExists) {		
			// Just create the role
			Set tGrantedResources = "%DB_%DEFAULT:RW,%DB_CACHETEMP:RW," _ tDBResource _ ":RW"
			Set tStatus = ##class(Security.Roles).Create(tRole,"EAI web services role",tGrantedResources)
			$$$ThrowOnError(tStatus)
			
			Do ..Log(.pLogFile,$Classname(),"ConfigureDefaultSecurity","Created default services role. " _ "Name: " _ tRole _ "|GrantedResources: " _ tGrantedResources)
		} Else {
			Do ..Log(.pLogFile,$Classname(),"ConfigureDefaultSecurity","Default services role " _ tRole _ " already exists")	
		}
		
		// Create the default user
		// Check if exists
		Set tExists = ##class(Security.Users).Exists(tUsername)
		If ('tExists) {
			// Create
			Set tStatus = ##class(Security.Users).Create(tUsername,tRole,tPassword,"ITF Web Services user",tNamespace,"","",0,1,"",,,,,1,1)
			$$$ThrowOnError(tStatus)
			
			Do ..Log(.pLogFile,$Classname(),"ConfigureDefaultSecurity","Created default services user. " _ "Username: " _ tUsername)
		} Else {
			Do ..Log(.pLogFile,$Classname(),"ConfigureDefaultSecurity","Default services user " _ tUsername _ " already exists")	
		}
		
	} Catch eException {
		Set tStatus = eException.AsStatus()
	}
	
	Quit tStatus

	Set tStatus = $$$OK
	Try {
		
		Set tNamespace = $GET(^EAI.Setting("Namespace"))
		Set tSourceDir = $GET(^EAI.Setting("SourceControlDirectory"))
		
		// Run this from new namespace
		New $NAMESPACE
   		Set $NAMESPACE = tNamespace
   		
		Do ..Log(.pLogFile,$Classname(),"ImportCode","Import code for " _ tNamespace _ " namespace ")
		
		Set tStatus = $System.OBJ.LoadDir(tSourceDir,"ck",.tErrorLog,1,.tLoadedList)
		$$$ThrowOnError(tStatus)
		
	} Catch eException {
		Set tStatus = eException.AsStatus()
	}
	
	Quit tStatus

Set tStatus = $$$OK Try {
Set tNamespace = $GET(^EAI.Setting("Namespace")) Set tConnectionName = $GET(^EAI.Setting("SQLGatewayConnectionName")) Set tURL = $GET(^EAI.Setting("SQLGatewayURL")) Set tUsername = $GET(^EAI.Setting("SQLGatewayUsername")) Set tPassword = $GET(^EAI.Setting("SQLGatewayPassword")) Set tDriver = $GET(^EAI.Setting("SQLGatewayDriver")) Set tClasspath = $GET(^EAI.Setting("SQLGatewayClasspath"))
// Run this from %SYS New $NAMESPACE Set $NAMESPACE = tNamespace
Do ..Log(.pLogFile,$Classname(),"ConfigureSQLGateway","Creating the SQL Gateway for connection " _ tConnectionName)
Set tExists = ##class(%Library.SQLConnection).ConnExists(tConnectionName)
If ('tExists) { Set tConnection = ##class(%Library.SQLConnection).%New() Set tConnection.Name = tConnectionName Set tConnection.URL = tURL Set tConnection.Usr = tUsername Set tConnection.pwd = tPassword Set tConnection.driver = tDriver Set tConnection.classpath = tClasspath
Set tConnection.isJDBC = 1 Set tConnection.useCAST = 0 Set tConnection.ReverseOJ = 0 Set tConnection.needlongdatalen = 0 Set tConnection.noconcat = "" Set tConnection.nodefq = 0 Set tConnection.nvl = 0 Set tConnection.properties = "" Set tConnection.useCASTCHAR = 0 Set tConnection.useCOALESCE = 1 Set tConnection.xadriver = ""
Set tStatus = tConnection.%Save() $$$ThrowOnError(tStatus)
Do ..Log(.pLogFile,$Classname(),"ConfigureSQLGateway","SQL Gateway for connection " _ tConnectionName _ " created") } Else { Do ..Log(.pLogFile,$Classname(),"ConfigureSQLGateway","SQL Gateway for connection " _ tConnectionName _ " already exists") } } Catch eException { Set tStatus = eException.AsStatus() }
Quit tStatus

	Set tStatus = $$$OK
	Try {
		
		Set tNamespace = $GET(^EAI.Setting("Namespace"))
		Set tPackageTarget = $GET(^EAI.Setting("PackageMappingTarget"))
		Set tPackageDatabaseLocation = $GET(^EAI.Setting("PackageMappingDatabaseLocation"))
		Set tPackageName = $GET(^EAI.Setting("PackageMappingPackageName"))
		Set tGlobalTarget = $GET(^EAI.Setting("GlobalMappingTarget"))
		Set tGlobalDatabaseLocation = $GET(^EAI.Setting("GlobalMappingDatabaseLocation"))
		Set tGlobalName = $GET(^EAI.Setting("GlobalMappingGlobalName"))
		
		// Global and Package mappings are configured in %SYS namespace
		New $NAMESPACE
   		Set $NAMESPACE = "%SYS"
		
		// Package mapping(s)...
		Do ..Log(.pLogFile,$Classname(),"ConfigureMappings","Creating package mapping for " _ tPackageDatabaseLocation _ ":" _ tPackageName _ " to target " _ tPackageTarget)
		
		Set tExists = ##class(Config.MapPackages).Exists(tPackageTarget,tPackageName)
		If ('tExists) {
			// Create it
			Kill tProperties
			Set tProperties("Database") = tPackageDatabaseLocation
			Set tStatus = ##class(Config.MapPackages).Create(tPackageTarget,tPackageName,.tProperties)
			$$$ThrowOnError(tStatus)
			
			Do ..Log(.pLogFile,$Classname(),"ConfigureMappings","Created new package mapping for " _ tPackageDatabaseLocation _ ":" _ tPackageName _ " to target " _ tPackageTarget)
		} Else {
			Do ..Log(.pLogFile,$Classname(),"ConfigureMappings","Package mapping for " _ tPackageDatabaseLocation _ ":" _ tPackageName _ " to target " _ tPackageTarget _ " already exists")
		}
		
		// Global mapping(s)...
		Do ..Log(.pLogFile,$Classname(),"ConfigureMappings","Creating global mapping for " _ tGlobalDatabaseLocation _ ":" _ tGlobalName _ " to target " _ tGlobalTarget)
		
		Set tExists = ##class(Config.MapGlobals).Exists(tGlobalTarget,tGlobalName)
		If ('tExists) {
			// Create it
			Kill tProperties
			Set tProperties("Database") = tGlobalDatabaseLocation
			Set tStatus = ##class(Config.MapGlobals).Create(tGlobalTarget,tGlobalName,.tProperties)
			$$$ThrowOnError(tStatus)
			
			Do ..Log(.pLogFile,$Classname(),"ConfigureMappings","Created new global mapping for " _ tGlobalDatabaseLocation _ ":" _ tGlobalName _ " to target " _ tGlobalTarget)
		} Else {
			Do ..Log(.pLogFile,$Classname(),"ConfigureMappings","global mapping for " _ tGlobalDatabaseLocation _ ":" _ tGlobalName _ " to target " _ tGlobalTarget _ " already exists")
		}
		
	} Catch eException {
		Set tStatus = eException.AsStatus()
	}
	
	Quit tStatus

Set tStatus = $$$OK Try {
Kill ^EAI.Setting
// Set the globals Set ^EAI.Setting("Namespace") = $GET(pOptions("Namespace"),"EAI") Set ^EAI.Setting("RoutineDatabase") = $GET(pOptions("RoutineDatabase"),"EAI") Set ^EAI.Setting("DataDatabase") = $GET(pOptions("DataDatabase"),"EAI") Set ^EAI.Setting("DatabaseResource") = $GET(pOptions("DatabaseResource"),"%DB_EAI") Set ^EAI.Setting("DatabasePublicPermissions") = $GET(pOptions("DatabasePublicPermissions"),"R") Set ^EAI.Setting("CSPAppName") = $GET(pOptions("CSPAppName"),"eai") Set ^EAI.Setting("DefaultServicesUsername") = $GET(pOptions("DefaultServicesUsername"),"ITF_Services") Set ^EAI.Setting("DefaultServicesPassword") = $GET(pOptions("DefaultServicesPassword"),"ITF_Services") Set ^EAI.Setting("DefaultServicesRole") = $GET(pOptions("DefaultServicesRole"),"ITF-WebServices") Set tSrcCtrlDir = ##class(%File).NormalizeDirectory("/WORK/eai/deploy/ensemble-dev/") Set ^EAI.Setting("SourceControlDirectory") = $GET(pOptions("SourceControlDirectory"),tSrcCtrlDir) Set ^EAI.Setting("SQLGatewayConnectionName") = $GET(pOptions("SQLGatewayConnectionName"),"EAITEAM") Set ^EAI.Setting("SQLGatewayURL") = $GET(pOptions("SQLGatewayURL"),"jdbc:oracle:thin:@//entrac1-scan.co.ihc.com:1521/tacprd40_ha.co.ihc.com") Set ^EAI.Setting("SQLGatewayUsername") = $GET(pOptions("SQLGatewayUsername"),"eaiteam") Set ^EAI.Setting("SQLGatewayPassword") = $GET(pOptions("SQLGatewayPassword"),"eaiteam") Set ^EAI.Setting("SQLGatewayDriver") = $GET(pOptions("SQLGatewayDriver"),"oracle.jdbc.driver.OracleDriver") Set tOJDBCDir = ##class(%File).NormalizeDirectory($System.Util.InstallDirectory()_"/eai/lib/ojdbc7.jar") Set ^EAI.Setting("SQLGatewayClasspath") = $GET(pOptions("SQLGatewayClasspath"),tOJDBCDir) Set ^EAI.Setting("PackageMappingTarget") = $GET(pOptions("PackageMappingTarget"),"%ALL") Set ^EAI.Setting("PackageMappingDatabaseLocation") = $GET(pOptions("PackageMappingDatabaseLocation"),"EAI") Set ^EAI.Setting("PackageMappingPackageName") = $GET(pOptions("PackageMappingPackageName"),"IHC.EAI") Set ^EAI.Setting("GlobalMappingTarget") = $GET(pOptions("GlobalMappingTarget"),"%ALL") Set ^EAI.Setting("GlobalMappingDatabaseLocation") = $GET(pOptions("GlobalMappingDatabaseLocation"),"EAI") Set ^EAI.Setting("GlobalMappingGlobalName") = $GET(pOptions("GlobalMappingGlobalName"),"IHC.EAI.Report.AuditLog.Data*")
} Catch eException { Set tStatus = eException.AsStatus() } Quit tStatus

	Set tStatus = $$$OK
	Try {
		
		Set tNamespace = $GET(^EAI.Setting("Namespace"))
		
		New $NAMESPACE
   		Set $NAMESPACE = tNamespace
   		
		Set tProductionClass = ^EAI.Setting("ProductionClass")
		
			
		// Shutdown existing production
		Set tStatus = ##class(IHC.EAI.Director).StopProduction(tNamespace,,.tInitialState,.tState,1)
		$$$ThrowOnError(tStatus)
		/*If ($$$ISERR(tStatus)) {
			Set tErrorMessage = $System.Status.GetErrorText(tStatus)
			Do ..Log(.pLogFile,$Classname(),"BuildDBNS","Failed to stop existing production: " _ tErrorMessage)
			Set tStatus = $$$OK
