		$$$ThrowOnError(tStatus)
		
		Set tStatus = $CLASSMETHOD("IHC.EAI.Director","StartProduction",tNamespace,tProductionClass,.tState)
		//Set tStatus = ##class(IHC.EAI.Director).StartProduction(tNamespace,tProductionClass,.tState)
		$$$ThrowOnError(tStatus)
		
	} Catch eException {
		Set tStatus = eException.AsStatus()
	}
	Quit tStatus

Set tStatus = $$$OK
Try {
	
} Catch eException {
	Set tStatus = eException.AsStatus()
