#Dim tResultSet As %SQL.StatementResult
Set tStatus = $$$OK Try {
Set tNamespace = $GET(^EAI.Setting("Namespace"))
New $NAMESPACE Set $NAMESPACE = tNamespace
// Create any needed default values Set tStatus = $CLASSMETHOD("IHC.EAI.System.Data.Instance","Init") //Set tStatus = ##class(IHC.EAI.System.Data.Instance).Init() $$$ThrowOnError(tStatus)
// Environment-dependent settings Set tStatus = ..GetEnvironment(.tEnvironment,.tInstanceType,.tInstanceName) $$$ThrowOnError(tStatus)
Set tPhysicalHost = "", tPhysicalPort = "" Set tQuery = "SELECT PhysicalHost,PhysicalPort,VirtualHost,VirtualPort,ServerHost,ServerPort " _ "FROM IHC_EAI_System_Data.Instance " _ "WHERE Name = ?"
Set tStatement = ##class(%SQL.Statement).%New() Set tStatus = tStatement.%Prepare(tQuery) $$$ThrowOnError(tStatus) Set tResultSet = tStatement.%Execute(tInstanceName)
If (tResultSet.%Next(.tStatus)) { $$$ThrowOnError(tStatus) Set tPhysicalHost = tResultSet.%GetData(1) Set tPhysicalPort = tResultSet.%GetData(2) Set tVirtualHost = tResultSet.%GetData(3) Set tVirtualPort = tResultSet.%GetData(4) Set tServerHost = tResultSet.%GetData(5) Set tServerPort = tResultSet.%GetData(6)
// These settings will only be set in the NS we are configuring Set ^EAI.Setting("PhysicalNodeHost") = tPhysicalHost Set ^EAI.Setting("PhysicalNodePort") = tPhysicalPort Set ^EAI.Setting("VirtualNodeHost") = tVirtualHost Set ^EAI.Setting("VirtualNodePort") = tVirtualPort Set ^EAI.Setting("ServerNodeHost") = tServerHost Set ^EAI.Setting("ServerNodePort") = tServerPort } $$$ThrowOnError(tStatus)
If ((tInstanceType = "MSGBK") || (tInstanceType = "SANDBOX")) { Set ^EAI.Setting("ProductionClass") = "IHC.EAI.Production.ServerNode" } Else { Set ^EAI.Setting("ProductionClass") = "IHC.EAI.Production.InterfaceNode" }
} Catch eException { Set tStatus = eException.AsStatus() } Quit tStatus

	Set tStatus = $$$OK
	Try {
		
		// Check on log dir
		Set tLogDir = ..fixPath($System.Util.ManagerDirectory() _ "EAILogs")

		Set tDirExists = ##class(%File).DirectoryExists(tLogDir)
		If ('tDirExists) {
			Set tCreateDir = ##class(%File).CreateDirectory(tLogDir)
			If ('tCreateDir) {
				$$$ThrowStatus($$$ERROR($$$GeneralError, "Failed to create EAILogs directory."))
			}
		}
		
		 // Just close ?
 		If ($GET(pClass) = 0) {
	 		Do:+$GET(pLogFile) pLogFile.Close()
	 		Quit
 		}

		// Make logfile object pLogFile
		If ('$DATA(pLogFile)) {
			Set tFilename = ..#LOGNAME _ "." _ $I(^%SYS("EAI","Log"))_".log"
			Set tFile = ##class(%File).NormalizeFilename(tFilename,tLogDir)
			Set pLogFile = ##class(%File).%New(tFile)
		}

		// Try to (re-)open if not open
		If (+pLogFile && 'pLogFile.IsOpen) {
			Do pLogFile.Open("WSA",2) // try for 2 seconds
			If ('pLogFile.IsOpen) {
				Write !, "Cannot open logfile ", pLogFile.Name
				Set pLogFile = 0
			}
		}

		// Write message to logfile and/or terminal
		Set tLine = pClass _ ":" _ pMethod _ " " _ pText
		If (+pLogFile) {
			Do pLogFile.WriteLine($ZTIME($PIECE($HOROLOG,",",2),1) _ " " _ tLine)
		}
		If ($LENGTH(pLogFile)) {
			Write !, tLine
		}
		
	} Catch eException {
		Set tStatus = eException.AsStatus()
	}
	Quit tStatus

If ""'=pPath {
	If $$$isVMS {
		Quit ##Class(%File).NormalizeDirectory(pPath)
	} ElseIf $$$isUNIX {
		Set pPath = $Translate(pPath,"\","/")
		Quit:("/" '= $E(pPath,*)) pPath_"/"
	} Else {
		Set pPath = $Translate(pPath,"/","\")
		Quit:("\" '= $E(pPath,*)) pPath_"\"
	}
}
Quit pPath

Set tStatus = $$$OK
Set pEnvironment = "", pInstanceType = ""
Try {
	Set pInstanceName = $ZCONVERT(##class(%SYS.System).GetInstanceName(),"U")
	If (pInstanceName [ "DEV") {
		Set pEnvironment = "DEV"
	} ElseIf (pInstanceName [ "QA") {
		Set pEnvironment = "QA"
	} ElseIf (pInstanceName [ "UAT") {
		Set pEnvironment = "UAT"
	} ElseIf ((pInstanceName [ "PRD") || (pInstanceName [ "PROD")) {
		Set pEnvironment = "PROD"
	}  ElseIf (pInstanceName [ "SAND") {
		Set pEnvironment = "SANDBOX"
	} Else {
		$$$ThrowStatus($$$ERROR($$$GeneralError, "Unknown environment: " _ pInstanceName))
	}
	
	If (pInstanceName [ "CLIN") {
		Set pInstanceType = "CLIN"
	} ElseIf (pInstanceName [ "PAYER") {
		Set pInstanceType = "PAYER"
	} ElseIf (pInstanceName [ "PROVIDER") {
		Set pInstanceType = "PROVIDER"
	} ElseIf (pInstanceName [ "MSGBK") {
		Set pInstanceType = "MSGBK"
	} ElseIf (pInstanceName [ "SAND") {
		Set pInstanceType = "SANDBOX"
	}  Else {
		$$$ThrowStatus($$$ERROR($$$GeneralError, "Unknown instance type: " _ pInstanceName))
	}
	
} Catch eException {
	Set tStatus  = eException.AsStatus()
}
Quit tStatus
